import{_ as o,o as t,c as e,ag as i}from"./chunks/framework.D5hoimZQ.js";const _=JSON.parse('{"title":"科学日报 · 2026-10-24（物理 / 声子热霍尔 / 反铁磁）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-10-24-physics.md","filePath":"topics/physics/science-daily-2026-10-24-physics.md"}'),c={name:"topics/physics/science-daily-2026-10-24-physics.md"};function a(r,s,n,l,d,g){return t(),e("div",null,[...s[0]||(s[0]=[i('<h1 id="科学日报-·-2026-10-24-物理-声子热霍尔-反铁磁" tabindex="-1">科学日报 · 2026-10-24（物理 / 声子热霍尔 / 反铁磁） <a class="header-anchor" href="#科学日报-·-2026-10-24-物理-声子热霍尔-反铁磁" aria-label="Permalink to &quot;科学日报 · 2026-10-24（物理 / 声子热霍尔 / 反铁磁）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> — 第43期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-physics</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（延续 10-21 起的确立做法，见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-24-声子热霍尔效应不只是「磁」——nips3-把信号钉在本征热力学起源上" tabindex="-1">科学日报 2026-10-24：声子热霍尔效应不只是「磁」——NiPS₃ 把信号钉在本征热力学起源上 <a class="header-anchor" href="#科学日报-2026-10-24-声子热霍尔效应不只是「磁」——nips3-把信号钉在本征热力学起源上" aria-label="Permalink to &quot;科学日报 2026-10-24：声子热霍尔效应不只是「磁」——NiPS₃ 把信号钉在本征热力学起源上&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ DOI: 10.1126/science.adt1992</p></blockquote><ul><li>悬而未决的问题：<strong>绝缘体中的热霍尔效应（thermal Hall effect）由声子贡献</strong>已观测多年，但机制未定 —— 到底是<strong>外禀</strong>（杂质/边界/声子-缺陷散射）还是<strong>本征</strong>（晶格/磁序本身赋予声子一个「等效的洛伦兹力」）。</li><li>材料：<strong>NiPS₃（磷硫化镍）</strong> —— 一种<strong>范德华层状蜂窝晶格</strong>，带<strong>锯齿状（zigzag）反铁磁序</strong>。选它是因为「磁序 + 蜂窝几何」同时提供可能的<strong>本征时间反演破缺</strong>来源。</li><li>判据（本篇的价值所在，两条互相独立的证据）： <ul><li><strong>纵向 κ_aa 与横向 κ_ab 在同一温度出峰</strong>，且峰处的<strong>热霍尔角</strong>遵守此前提出的一个<strong>理论上界</strong> → 横向响应不是散射偶然事件，而是与纵向输运同一套声子态在起作用。</li><li><strong>κ_ab 幅度对沿 b 轴的磁化极为敏感，却与声子平均自由程不相关</strong> → 排除「声子自由程越长、霍尔越强」的外禀图像，指向<strong>本征（谱学）起源</strong>。</li></ul></li><li>结论：声子热霍尔响应的<strong>幅度由磁序（沿 b 轴磁化）而非散射长度决定</strong>，这是「本征机制」的一次干净分离。</li><li>洞察（对本库 <code>physics</code> × <code>materials</code>）：本条给出的是一条<strong>可复用的实验判据</strong>——「<strong>要判定一个输运效应的外禀/本征，就找一对『应该同步』与一对『应该脱钩』的观测量</strong>」（这里是 κ_aa/κ_ab 同步、κ_ab/平均自由程 脱钩）。这比争论模型更硬。与本库 10-23 的「反铁磁八极矩 → OTT 电流翻转」是同一条主线的两面：<strong>反铁磁体过去因『没有净磁矩』被判死，如今连续在两个效应上被复活</strong>（一个是电荷输运的 TMR/自旋矩，一个是热输运的声子霍尔）；共同教益是「<strong>判死一个效应前，先问用的是哪个序参量、哪个输运势垒</strong>」。迁移到外脑：<strong>当一个结论被「对称性/不存在」类论证否定时，先把论证里隐含的观测通道显式写出来，再问换一条通道是否仍然成立。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ 第43期 科学板块</p></blockquote><p>关键词：声子热霍尔效应、thermal Hall effect、NiPS3、磷硫化镍、范德华、蜂窝晶格、zigzag 反铁磁、κ_aa 与 κ_ab 同温出峰、热霍尔角上界、κ_ab 对 b 轴磁化敏感、与声子平均自由程不相关、本征 vs 外禀、时间反演破缺、判死效应前先问观测通道、反铁磁连续被复活</p><p>关联：<code>topics/materials/science-daily-2026-10-23-materials.md</code>（反铁磁八极矩 OTT）、<code>topics/physics/science-daily-2026-10-23-physics.md</code>（电流驱动分子机器）、<code>topics/physics/index.md</code></p>',10)])])}const h=o(c,[["render",a]]);export{_ as __pageData,h as default};
